mapper.select:
		/** [sql-fault.xml] FaultMapper.getSeq **/
		SELECT COALESCE(MAX(ST08_SEQ)+1,1) AS ST08_SEQ
          FROM TB_ST_08
          WHERE ST08_COMPANY = #{st08Company}
            AND ST08_FACTORY = #{st08Factory}
            AND TO_CHAR(ST08_DAT, 'YYYYMMDD') = TO_CHAR(TO_DATE(#{st08Dat}, 'YYYYMMDDHH24MI'), 'YYYYMMDD')

/** [sql-fault.xml] FaultMapper.getFaultInfo **/
SELECT * FROM TB_ST_08
WHERE 1=1
AND ST08_COMPANY = #{st08Company}
AND ST08_FACTORY = #{st08Factory}
AND ST08_NO		 = CONCAT(TO_CHAR(TO_DATE(#{st08Dat}, 'YYMMDDHH24MI'), 'YYYYMMDD'), LPAD(#{st08Seq}, 5, '0'))

mapper.insert:
    	/** [sql-fault.xml] FaultMapper.insertOfFault **/
        INSERT INTO TB_ST_08
		(
			  ST08_COMPANY
			, ST08_FACTORY
			, ST08_NO
			, ST08_DAT
			, ST08_SEQ
			, ST08_GBN
			, ST08_PGBN
			, ST08_CODE
			, ST08_UNT
			, ST08_LOT
			, ST08_RMK
			, ST08_STOK
			, ST08_INDTE
			, ST08_EMPNO
			, ST08_QTY
			, ST08_DIST
			, ST08_LOT_SEQ
			, ST08_QRCODE
		)
		VALUES
		(
			  #{st08Company}
			, #{st08Factory}
			, CONCAT(TO_CHAR(TO_DATE(#{st08Dat}, 'YYMMDDHH24MI'), 'YYYYMMDD'), LPAD(#{st08Seq}, 5, '0'))
			, TO_DATE(#{st08Dat}, 'YYMMDDHH24MI')
			, #{st08Seq}
			, #{st08Gbn}
			, NULL
			, #{st08Code}
			, NULL
			, #{st08Lot}
			, NULL
			, #{st08Stok}
			, SYSDATE
			, #{st08Empno}
			, 1
			, #{st08Dist}
			, #{st08LotSeq}
			, #{st08Qrcode}
		)
